const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
const slot5 = (value) => ((Math.floor(Number.isFinite(value) ? value : 0) % 5) + 5) % 5;
function dense(input, normalMin, criticalMin, familyOffset, reducedMotion = false, reducedFlash = false) { const active = Math.max(1, Math.floor(input.activeCount)), rank = Math.max(0, Math.floor(input.indexFromNewest)), slot = slot5(rank + familyOffset), openSlots = active >= 10 ? 1 : active >= 5 ? 2 : 3, admitted = slot < openSlots, load = clamp01(input.stress), phase = clamp01(input.phase), ageScale = Math.max(.68, 1 - Math.min(1, rank / Math.max(1, active - 1)) * .28), base = admitted ? .9 - load * .1 : (input.critical ? .66 : .46) - load * .08, phaseScale = .9 + .1 * (1 - Math.abs(phase - .5) * 2), motion = reducedMotion ? .97 : 1, flash = reducedFlash ? .95 : 1, minimum = input.critical ? criticalMin : normalMin, secondaryScale = clamp01(Math.max(minimum, base * ageScale * phaseScale) * motion * flash); return { slot, openSlots, admitted, primaryScale: 1, secondaryScale, presentationOnly: true }; }
export function denseProjectileThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return dense(input, .34, .5, 0, reducedMotion, reducedFlash); }
export function denseImpactThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return dense(input, .32, .5, 1, reducedMotion, reducedFlash); }
export function denseHazardThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return dense(input, .34, .52, 2, reducedMotion, reducedFlash); }
export function denseSafeLaneThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return { ...dense(input, .42, .62, 4, reducedMotion, reducedFlash), safeLaneScale: 1, presentationOnly: true }; }
export function denseSpecialistThreatRhythmPresentation(input, reducedMotion = false, reducedFlash = false) { return dense(input, .34, .54, 3, reducedMotion, reducedFlash); }
export function denseThreatRhythmBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const active = Math.max(0, Math.floor(input.activeCount)), load = clamp01(input.stress), critical = clamp01(Math.max(0, input.criticalCount) / 3), laneReserve = input.safeLaneVisible ? .08 : 0, maxConcurrentPeaks = active >= 10 ? 1 : active >= 5 ? 2 : 3, secondaryScale = Math.max(.46, 1 - load * .34 - critical * .04 - laneReserve) * (reducedMotion ? .97 : 1) * (reducedFlash ? .95 : 1); return { maxConcurrentPeaks, primaryScale: 1, secondaryScale: clamp01(secondaryScale), safeLaneScale: 1, presentationOnly: true }; }
